// Mongoose schemas written by Model2DB from Order. Review them before using them.
import { Schema, model } from 'mongoose'

const addressSchema = new Schema(
  {
    street: { type: String, required: true },
    city: { type: String, required: true },
    postal_code: { type: String, required: true },
    country: { type: String, required: true },
  },
  { _id: false },
)

const customerSchema = new Schema(
  {
    id: { type: Number, required: true },
    email: { type: String, required: true },
    full_name: { type: String, required: true },
    phone: String,
    shipping_address: { type: addressSchema, required: true },
    created_at: { type: Date, required: true },
  },
  { _id: false },
)

const orderLineSchema = new Schema(
  {
    product: { type: Number, ref: 'Product' },
    quantity: { type: Number, required: true },
    unit_price: { type: Number, required: true },
  },
  { _id: false },
)

const orderSchema = new Schema(
  {
    _id: Number,
    customer: { type: customerSchema, required: true },
    status: { type: String, required: true, enum: ['draft', 'paid', 'shipped', 'cancelled'] },
    lines: [orderLineSchema],
    coupon_code: { type: String, default: null },
    tags: [String],
    placed_at: { type: Date, required: true },
  },
  { collection: 'order', versionKey: false },
)
orderSchema.index({ 'customer.email': 1 }, { name: 'uq_order_customer_email', unique: true })
orderSchema.index({ 'lines.product': 1 }, { name: 'ix_order_lines_product' })

const productSchema = new Schema(
  {
    _id: Number,
    sku: { type: String, required: true },
    name: { type: String, required: true },
    price: { type: Number, required: true },
    categories: [{ type: Number, ref: 'Category' }],
    attributes: { type: Map, of: String },
  },
  { collection: 'product', versionKey: false },
)
productSchema.index({ 'sku': 1 }, { name: 'uq_product_sku', unique: true })

const categorySchema = new Schema(
  {
    _id: Number,
    name: { type: String, required: true },
    products: [{ type: Number, ref: 'Product' }],
  },
  { collection: 'category', versionKey: false },
)

export const Order = model('Order', orderSchema)
export const Product = model('Product', productSchema)
export const Category = model('Category', categorySchema)

